const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const allowed = ['project.created', 'project.updated', 'approval.requested'];
const event = typeof input.event === 'string' ? input.event : '';
const projectId = typeof input.projectId === 'string' ? input.projectId.trim() : '';
if (!allowed.includes(event)) return [{ json: { success: false, error: 'Unsupported project event.' } }];
if (!projectId) return [{ json: { success: false, error: 'projectId is required.' } }];
const locale = input.locale === 'es' ? 'es' : 'en';
const labels = {
  en: {
    'project.created': 'Project created',
    'project.updated': 'Project updated',
    'approval.requested': 'Approval requested'
  },
  es: {
    'project.created': 'Proyecto creado',
    'project.updated': 'Proyecto actualizado',
    'approval.requested': 'Aprobación solicitada'
  }
};
const message = `${labels[locale][event]} · ${projectId}`;
return [{ json: { success: true, locale, notification: { message, date: new Date().toISOString().slice(0, 10) } } }];
